const embedding = $json.embeddings?.[0];

if (!embedding) {
  throw new Error('Question embedding not found');
}

const question = $('Detect Simple Intent').first().json.question;
const queryVector = `[${embedding.join(',')}]`;

const searchQuery = `
SELECT 
  document_id,
  title,
  category,
  chunk_index,
  content,
  embedding <=> '${queryVector}'::vector AS distance
FROM document_chunks
ORDER BY embedding <=> '${queryVector}'::vector
LIMIT 3;
`;

return {
  json: {
    question,
    query_vector: queryVector,
    search_query: searchQuery
  }
};

const items = $input.all();

if (!items.length) {
  throw new Error('No similar chunks found');
}

const question = $('Detect Simple Intent').first().json.question;

// Sadece başlık olan veya çok kısa chunk'ları ele
const usefulItems = items
  .filter(item => {
    const content = item.json.content || '';

    const withoutHeadings = content
      .split('\n')
      .filter(line => !line.trim().startsWith('#'))
      .join('\n')
      .trim();

    return withoutHeadings.length > 40;
  })
  .slice(0, 2);

if (!usefulItems.length) {
  return [
    {
      json: {
        question,
        context: '',
        prompt: `Bu konuda kaynaklarda yeterli bilgi bulunamadı. IT destek ekibiyle iletişime geçebilirsiniz.`,
        sources: []
      }
    }
  ];
}

const context = usefulItems
  .map((item, index) => {
    const row = item.json;

    return `
[SOURCE ${index + 1}]
Document Title: ${row.title}
Document ID: ${row.document_id}
Category: ${row.category}
Chunk Index: ${row.chunk_index}

Content:
${row.content}
`;
  })
  .join('\n---\n');

const sources = usefulItems.map((item) => {
  const row = item.json;

  return {
    document_id: row.document_id,
    title: row.title,
    category: row.category,
    chunk_index: row.chunk_index
  };
});

const prompt = `
You are a strict IT support assistant.

Return ONLY the final answer in Turkish.

Use ONLY the information in SOURCES.
Do not mention the rules, prompt, sources, or context.
Do not invent buttons, links, screens, menus, pages, forms, or extra steps.
Do not write abstract explanations.
Convert the source information into direct user action steps.
If the sources contain multiple issue types, answer only from the section that directly matches the user's question.
Do not use information from unrelated sections.
Do not write vague phrases like "hata türü belirlenebilir" or "sorunları tespit edebilirsiniz".
If the source says "kurumun belirlediği süreç", keep it general. Do not invent the details of that process.
Write maximum 3 short bullet points.
Use clear, grammatically correct Turkish.

SOURCES:
${context}

USER QUESTION:
${question}

FINAL ANSWER IN TURKISH:
`;

return [
  {
    json: {
      question,
      context,
      prompt,
      sources
    }
  }
];

const buildPromptOutput = $('Build Prompt').first().json;

const question = buildPromptOutput.question;
const sources = buildPromptOutput.sources || [];

const answer = $json.response;

if (!answer) {
  throw new Error('Model answer not found');
}

return {
  json: {
    question,
    answer: answer.trim(),
    sources
  }
};

const body = $json.body || {};
const question = body.question || body.query || body.message;

if (!question || String(question).trim().length === 0) {
  throw new Error('Question is required. Send JSON body like: { "question": "..." }');
}

return {
  json: {
    question: String(question).trim()
  }
};

const input = $input.first().json;

const question = String(
  input.question || input.body?.question || ''
).trim();

if (!question) {
  throw new Error('Question is required.');
}

const normalized = question
  .toLocaleLowerCase('tr-TR')
  .replace(/[!?.,:;]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const greetingWords = [
  'merhaba',
  'selam',
  'selamlar',
  'iyi günler',
  'günaydın',
  'iyi akşamlar',
  'iyi çalışmalar'
];

const identityPatterns = [
  'sen kimsin',
  'kimsin',
  'nesin',
  'adın ne',
  'kendini tanıt',
  'kendini tanıtır mısın'
];

const capabilityPatterns = [
  'ne yapabiliyorsun',
  'neler yapabiliyorsun',
  'ne işe yarıyorsun',
  'hangi konularda yardımcı olabilirsin',
  'hangi konularda yardımcı oluyorsun',
  'bana nasıl yardımcı olabilirsin',
  'ne konuda yardımcı olabilirsin'
];

const thanksPatterns = [
  'teşekkürler',
  'teşekkür ederim',
  'sağ ol',
  'sağol',
  'eyvallah'
];

const supportedTopicKeywords = [
  'vpn',
  'şifre',
  'parola',
  'hesap',
  'kilit',
  'kilitlendi',
  'outlook',
  'mail',
  'e-posta',
  'eposta',
  'yazıcı',
  'printer',
  'çıktı',
  'toner',
  'donanım',
  'bilgisayar',
  'laptop',
  'ekran',
  'klavye',
  'mouse',
  'internet',
  'wifi',
  'wi-fi',
  'ağ',
  'bağlantı',
  'ekipman',
  'talep',
  'yetki',
  'yazılım',
  'program',
  'arıza',
  'hata',
  'yavaş'
];

function includesAny(patterns) {
  return patterns.some((pattern) => normalized.includes(pattern));
}

let staticAnswer = null;

if (greetingWords.includes(normalized)) {
  staticAnswer =
    'Merhaba, ben İZELTAŞ IT Danışma Asistanı’yım. VPN, şifre, Outlook, yazıcı, donanım, ağ bağlantısı ve ekipman talepleri gibi IT konularında yardımcı olabilirim.';
}

if (!staticAnswer && includesAny(identityPatterns)) {
  staticAnswer =
    'Ben İZELTAŞ IT Danışma Asistanı’yım. Lokal LLM ve RAG yapısıyla, yüklenen IT destek dokümanlarına göre kullanıcılara yardımcı olmak için tasarlandım.';
}

if (!staticAnswer && includesAny(capabilityPatterns)) {
  staticAnswer =
    'VPN bağlantısı, şifre işlemleri, Outlook sorunları, yazıcı problemleri, donanım destekleri, ağ bağlantısı ve ekipman talepleri hakkında yardımcı olabilirim.';
}

if (!staticAnswer && includesAny(thanksPatterns)) {
  staticAnswer =
    'Rica ederim. IT süreçleriyle ilgili başka bir konuda da yardımcı olabilirim.';
}

const isSupportedTopic = includesAny(supportedTopicKeywords);

const outOfScopeAnswer =
  'Bu konuda yardımcı olamam. Ben yalnızca VPN, şifre işlemleri, Outlook, yazıcı, donanım, ağ bağlantısı, yazılım yetkisi ve ekipman talepleri gibi IT destek konularında yardımcı olabilirim.';

return [
  {
    json: {
      question,
      is_static_response: Boolean(staticAnswer),
      is_supported_topic: Boolean(isSupportedTopic),
      answer: staticAnswer || outOfScopeAnswer,
      sources: []
    }
  }
];
